CREATE TABLE commands (
        id TEXT PRIMARY KEY,
        commandId TEXT NOT NULL UNIQUE,
        deviceId TEXT NOT NULL,
        commandType TEXT NOT NULL,
        state TEXT NOT NULL,
        actorType TEXT NOT NULL,
        actorId TEXT,
        payloadJson TEXT,
        payloadSummary TEXT,
        submittedAt TEXT NOT NULL,
        dispatchedAt TEXT,
        executingAt TEXT,
        finishedAt TEXT,
        outcome TEXT,
        reasonCode TEXT,
        reasonDetail TEXT,
        reqSeq INTEGER,
        createdAt TEXT NOT NULL DEFAULT (datetime('now')),
        FOREIGN KEY (deviceId) REFERENCES devices(id)
      );
CREATE TABLE command_audit (
        id TEXT PRIMARY KEY,
        commandId TEXT NOT NULL,
        ts TEXT NOT NULL,
        eventType TEXT NOT NULL,
        actorType TEXT,
        actorId TEXT,
        source TEXT NOT NULL,
        summary TEXT NOT NULL,
        detailsJson TEXT,
        createdAt TEXT NOT NULL DEFAULT (datetime('now')),
        FOREIGN KEY (commandId) REFERENCES commands(commandId)
      );
CREATE TABLE pty_sessions (
        id TEXT PRIMARY KEY,
        sessionId TEXT NOT NULL UNIQUE,
        deviceId TEXT NOT NULL,
        state TEXT NOT NULL,
        openedByActorType TEXT,
        openedByActorId TEXT,
        attachedActorType TEXT,
        attachedActorId TEXT,
        recordingEnabled INTEGER NOT NULL DEFAULT 0,
        recordingConsentAt TEXT,
        cols INTEGER,
        rows INTEGER,
        openedAt TEXT NOT NULL,
        lastAttachedAt TEXT,
        lastDetachedAt TEXT,
        lastOutputAt TEXT,
        closeRequestedAt TEXT,
        closedAt TEXT,
        expiredAt TEXT,
        failureCode TEXT,
        failureDetail TEXT,
        createdAt TEXT NOT NULL DEFAULT (datetime('now')), deletedAt TEXT,
        FOREIGN KEY (deviceId) REFERENCES devices(id)
      );
CREATE TABLE pty_audit (
        id TEXT PRIMARY KEY,
        sessionId TEXT NOT NULL,
        deviceId TEXT NOT NULL,
        ts TEXT NOT NULL,
        eventType TEXT NOT NULL,
        actorType TEXT,
        actorId TEXT,
        summary TEXT NOT NULL,
        detailsJson TEXT,
        createdAt TEXT NOT NULL DEFAULT (datetime('now')),
        FOREIGN KEY (deviceId) REFERENCES devices(id),
        FOREIGN KEY (sessionId) REFERENCES pty_sessions(sessionId)
      );
CREATE TABLE file_transfers (
        id TEXT PRIMARY KEY,
        transferId TEXT NOT NULL UNIQUE,
        deviceId TEXT NOT NULL,
        serverId TEXT NOT NULL,
        browserSessionId TEXT,
        actorType TEXT,
        actorId TEXT,
        state TEXT NOT NULL,
        direction TEXT NOT NULL,
        localPath TEXT,
        remotePath TEXT,
        recursive INTEGER NOT NULL DEFAULT 0,
        overwritePolicy TEXT,
        followSymlinks INTEGER NOT NULL DEFAULT 0,
        rateLimitKbps INTEGER,
        verifyChecksum INTEGER NOT NULL DEFAULT 0,
        preserveMtime INTEGER NOT NULL DEFAULT 0,
        preserveMode INTEGER NOT NULL DEFAULT 0,
        bytesTransferred INTEGER NOT NULL DEFAULT 0,
        bytesTotal INTEGER,
        percent REAL,
        throughputBps REAL,
        etaSec REAL,
        phase TEXT,
        reasonCode TEXT,
        reasonDetail TEXT,
        message TEXT,
        commandId TEXT,
        reqSeq INTEGER,
        startedAt TEXT,
        finishedAt TEXT,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 1, maxAttempts INTEGER NOT NULL DEFAULT 1, resumeSupported INTEGER NOT NULL DEFAULT 0, retryScheduled INTEGER NOT NULL DEFAULT 0, progressEventCount INTEGER NOT NULL DEFAULT 0, firstProgressAt TEXT, lastProgressAt TEXT, finalizeSeen INTEGER NOT NULL DEFAULT 0, resumeToken TEXT, resumeOffsetBytes INTEGER, tempPathHint TEXT, sessionId TEXT,
        FOREIGN KEY (deviceId) REFERENCES devices(id)
      );
CREATE TABLE remote_browser_sessions (
        id TEXT PRIMARY KEY,
        browserSessionId TEXT NOT NULL UNIQUE,
        deviceId TEXT NOT NULL,
        serverId TEXT NOT NULL,
        actorType TEXT,
        actorId TEXT,
        state TEXT NOT NULL,
        rootPath TEXT,
        currentPath TEXT,
        failureCode TEXT,
        failureDetail TEXT,
        openedAt TEXT NOT NULL,
        lastActiveAt TEXT,
        closedAt TEXT,
        createdAt TEXT NOT NULL,
        updatedAt TEXT NOT NULL,
        FOREIGN KEY (deviceId) REFERENCES devices(id)
      );
CREATE TABLE rate_limit_buckets (
        key TEXT PRIMARY KEY,
        count INTEGER NOT NULL,
        resetAt INTEGER NOT NULL
      );
